// ===== EDIT THESE BEFORE ACTIVATING =====
return [{
  json: {
    yourName: 'YOUR NAME',
    yourPhone: 'YOUR PHONE',
    yourAddress: 'YOUR BUSINESS POSTAL ADDRESS', // required by CAN-SPAM
    dailyLimit: 25,                              // keep 20-30 per inbox per day
    leadStatuses: ['HOT', 'WARM'],               // which leads get emails
    followUpDays: [2, 4, 7],                     // gap after email 1, 2, 3
  },
}];

// Picks which leads get an email today and writes the message.
const s = $('Settings').first().json;
if ([s.yourName, s.yourPhone, s.yourAddress].some((v) => /^YOUR /.test(String(v)))) {
  throw new Error('Open the Settings node and fill in your name, phone and postal address first.');
}
const rows = $input.all().map((i) => i.json);
const now = Date.now();
const today = new Date().toISOString().slice(0, 10);
const DAY = 24 * 60 * 60 * 1000;
const STOP = ['replied', 'opted_out', 'finished', 'bounced'];
const allowed = s.leadStatuses.map((x) => x.toUpperCase());

const TEMPLATES = [
  {
    subject: (c) => `missed calls at ${c.company}`,
    body: (c) => `Hi ${c.company} team,

Quick question: when you're on a job in ${c.city} and the phone rings, who picks up?

For most HVAC shops I talk to, the answer is "voicemail", and that customer calls the next company on Google.

I set up a simple system: every missed call gets an instant text from your business, the customer's problem and address get collected, and the job gets booked. Emergencies go straight to you.

Worth a 10-minute demo? You can text it like a real customer.`,
  },
  {
    subject: (c) => `re: missed calls at ${c.company}`,
    body: (c) => `Hi ${c.company} team,

A quick number to think about: if you miss just 5 calls a week and 1 in 3 would have booked, at around $300 a job that's roughly $2,000 a month going to competitors.

Want me to show you how the text-back works? It takes 10 minutes.`,
  },
  {
    subject: () => 'free 14-day test?',
    body: (c) => `Hi ${c.company} team,

Easier idea: I'll set it up free for 14 days. If it doesn't book you any extra jobs, you owe nothing.

Want me to set it up this week?`,
  },
  {
    subject: () => 'closing your file',
    body: (c) => `Hi ${c.company} team,

I haven't heard back, so I'll assume the timing isn't right. I won't email again.

If missed calls ever become a headache, just reply to this email.`,
  },
];

const footer = `

${s.yourName}
${s.yourPhone} · ${s.yourAddress}
Not interested? Reply "no" and I won't email again.`;

const sentToday = rows.filter((r) => String(r.last_email_at || '').startsWith(today)).length;
let remaining = Math.max(0, s.dailyLimit - sentToday);

// Follow-ups first, then highest score.
rows.sort((a, b) =>
  (Number(b.email_step) || 0) - (Number(a.email_step) || 0) ||
  (Number(b.lead_score) || 0) - (Number(a.lead_score) || 0)
);

const seen = new Set();
const out = [];

for (const r of rows) {
  if (remaining <= 0) break;
  const email = String(r.email || '').trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(email) || seen.has(email)) continue;
  seen.add(email); // one sequence per email address, even if it appears twice
  if (STOP.includes(String(r.email_status || '').toLowerCase())) continue;
  if (!allowed.includes(String(r.lead_status || '').trim().toUpperCase())) continue;

  const step = parseInt(r.email_step, 10) || 0;
  if (step >= TEMPLATES.length) continue;
  if (step > 0 && r.next_send_at && Date.parse(r.next_send_at) > now) continue;

  const c = {
    company: String(r.business_name || 'there').trim(),
    city: String(r.search_location || '').split(',')[0].trim() || 'your area',
  };
  const t = TEMPLATES[step];
  const nextStep = step + 1;
  const isLast = nextStep >= TEMPLATES.length;

  out.push({
    json: {
      place_id: r.place_id,
      email,
      subject: t.subject(c),
      body: t.body(c) + footer,
      email_step: nextStep,
      email_status: isLast ? 'finished' : 'active',
      next_send_at: isLast ? '' : new Date(now + s.followUpDays[step] * DAY).toISOString(),
    },
  });
  remaining--;
}

return out;

// Turns a reply in your inbox into a status for that lead.
// Any reply stops the sequence; "no/stop/unsubscribe" marks them opted out.
const EMAIL = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i;

return $input.all().map((i) => {
  const m = i.json;
  const fromRaw = String(
    m.From || (m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || ''
  );
  const snippet = String(m.snippet || m.text || '').replace(/\s+/g, ' ').slice(0, 300);

  let email = ((fromRaw.match(EMAIL) || [''])[0]).toLowerCase();
  let status =
    /\b(stop|unsubscribe|remove me|take me off|not interested|no thanks)\b/i.test(snippet) ||
    /^\s*no\b/i.test(snippet)
      ? 'opted_out'
      : 'replied';

  // Bounce: the failed address is inside the bounce message.
  if (/mailer-daemon|postmaster/i.test(fromRaw)) {
    email = ((snippet.match(EMAIL) || [''])[0]).toLowerCase();
    status = 'bounced';
  }

  return { json: { email, email_status: status, reply_snippet: snippet, replied_at: new Date().toISOString() } };
}).filter((x) => x.json.email);
